NUL = -1

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def minIncrements(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    f = [0] * n
    cost = 0
    for k in range(n - 1, -1, -1):
        a, b = left[k], right[k]
        if a != -1 and b != -1:
            cost += abs(f[a] - f[b])
            f[k] = vals[k] + max(f[a], f[b])
        elif a != -1:
            f[k] = vals[k] + f[a]
        elif b != -1:
            f[k] = vals[k] + f[b]
        else:
            f[k] = vals[k]
    return cost
